const researchFields = [
  'description', 'auth_methods', 'credential_acquisition', 'access_model',
  'api_type', 'api_breadth', 'mcp_available', 'buildability', 'blocker'
];
const hasResearch = row => researchFields.some(f => String(row[f] ?? '').trim() !== '');

// Only rows that have actually been researched (skip empty rows).
const research = $('Get Original Research').all().filter(i => hasResearch(i.json));

// Totals and accuracy come from the "calculate" node.
const summary = $input.first().json;

// Per-app comparison results, used for the mismatch counts.
const compared = $('compare results').all();

function normalize(value) {
  if (value === null || value === undefined || String(value).trim() === '') return 'unknown';
  return String(value).trim().toLowerCase();
}
function addCount(obj, value) { obj[value] = (obj[value] || 0) + 1; }

const accessModel = {}, apiBreadth = {}, mcpAvailability = {};
const buildability = {}, confidence = {}, categoryDistribution = {};
const authMethods = {};
const commonBlockers = {};
const verificationMismatchFields = {};

// Blockers are free text, so they are grouped by keyword.
// One blocker can fall into more than one group; anything else is "other".
const blockerGroups = [
  ['sales_or_contract', /sales|contact us|contract|enterprise|quote/],
  ['partner_or_approval', /partner|approval|approved|review process|allowlist|whitelist|application/],
  ['paid_plan_required', /paid|premium|subscription|billing|pricing|tier|licen[cs]e/],
  ['admin_required', /admin|administrator|tenant/],
  ['no_public_api', /no (public |official )?api|deprecated|discontinued|not available/]
];

for (const item of research) {
  const row = item.json;

  addCount(accessModel, normalize(row.access_model));
  addCount(apiBreadth, normalize(row.api_breadth));
  addCount(mcpAvailability, normalize(row.mcp_available));
  addCount(buildability, normalize(row.buildability));
  addCount(confidence, normalize(row.confidence));
  addCount(categoryDistribution, normalize(row.category));

  const auth = row.auth_methods;
  const list = Array.isArray(auth) ? auth : String(auth ?? '').split(',');
  const clean = list.map(x => String(x).trim().toLowerCase()).filter(Boolean);
  if (clean.length === 0) addCount(authMethods, 'unknown');
  else clean.forEach(m => addCount(authMethods, m));

  const blocker = normalize(row.blocker);
  const noBlocker = blocker === 'unknown' || blocker === 'none'
    || blocker.startsWith('no major blocker') || blocker.startsWith('none identified');
  if (!noBlocker) {
    let hit = false;
    for (const [name, re] of blockerGroups) {
      if (re.test(blocker)) { addCount(commonBlockers, name); hit = true; }
    }
    if (!hit) addCount(commonBlockers, 'other');
  }
}

for (const item of compared) {
  const list = String(item.json.mismatched_fields_list || '');
  list.split(',').map(x => x.trim()).filter(Boolean)
    .forEach(f => addCount(verificationMismatchFields, f));
}

return [{
  json: {
    analysis_type: 'research_vs_verification',
    total_apps: research.length,
    ...summary,
    access_model_distribution: accessModel,
    api_breadth_distribution: apiBreadth,
    mcp_availability_distribution: mcpAvailability,
    buildability_distribution: buildability,
    confidence_distribution: confidence,
    authentication_method_distribution: authMethods,
    category_distribution: categoryDistribution,
    common_blockers: commonBlockers,
    verification_mismatch_fields: verificationMismatchFields
  }
}];

const items = $('compare results').all();

const count = s => items.filter(i => i.json.comparison_status === s).length;

const notResearched = count('not_researched');
const notVerified = count('not_verified');
const matches = count('match');
const mismatches = count('mismatch');

const researched = items.length - notResearched;

const matchedFields = items.reduce((s, i) => s + Number(i.json.matched_fields || 0), 0);
const mismatchedFields = items.reduce((s, i) => s + Number(i.json.mismatched_fields || 0), 0);
const comparedFields = matchedFields + mismatchedFields;

const fieldAccuracy = comparedFields > 0
  ? Number(((matchedFields / comparedFields) * 100).toFixed(2)) : 0;

const appAgreement = (matches + mismatches) > 0
  ? Number(((matches / (matches + mismatches)) * 100).toFixed(2)) : 0;

return [{
  json: {
    total_researched_apps: researched,
    total_verified_apps: researched - notVerified,
    total_matches: matches,
    total_mismatches: mismatches,
    total_not_verified: notVerified,
    matched_fields: matchedFields,
    mismatched_fields: mismatchedFields,
    compared_fields: comparedFields,
    field_accuracy_percent: fieldAccuracy,
    app_agreement_percent: appAgreement
  }
}];

const original = $('Get Original Research').all();
const verified = $('Get verification results').all();

// If the verification tab has several rows for one id, the LAST one wins.
const verifiedMap = new Map();
for (const item of verified) {
  const id = String(item.json.id ?? '').trim();
  if (id) verifiedMap.set(id, item.json);
}

// Only short, controlled fields can be compared reliably.
// Free-text fields (description, credential_acquisition, blocker) are worded
// differently by every model run, so they would almost always show as mismatches.
const fields = [
  'auth_methods',
  'access_model',
  'api_type',
  'api_breadth',
  'mcp_available',
  'buildability'
];
const listFields = new Set(['auth_methods', 'api_type']);

// Used only to decide whether a research row has been filled in at all.
const researchFields = [
  'description', 'auth_methods', 'credential_acquisition', 'access_model',
  'api_type', 'api_breadth', 'mcp_available', 'buildability', 'blocker'
];

function token(s) {
  let t = String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
  if (t === 'oauth20') t = 'oauth2';
  return t;
}

function normalize(value, field) {
  if (value === null || value === undefined) return '';
  let parts;
  if (Array.isArray(value)) {
    parts = value.map(String);
  } else if (listFields.has(field)) {
    parts = String(value).split(/[,|;]/);
  } else {
    return token(value);
  }
  // order-independent: "OAuth2, API Key" equals "API Key, OAuth2"
  return parts.map(token).filter(Boolean).sort().join('|');
}

function hasResearch(row) {
  return researchFields.some(f => String(row[f] ?? '').trim() !== '');
}

const results = [];

for (const item of original) {
  const o = item.json;
  const id = String(o.id ?? '').trim();
  const base = { id: o.id, app: o.app, category: o.category };

  // Research not done yet for this row: nothing to compare.
  if (!hasResearch(o)) {
    results.push({ json: { ...base, comparison_status: 'not_researched',
      matched_fields: 0, mismatched_fields: 0, mismatched_fields_list: '', verification_confidence: '' } });
    continue;
  }

  const v = verifiedMap.get(id);

  // No verification record for this row.
  if (!v) {
    results.push({ json: { ...base, comparison_status: 'not_verified',
      matched_fields: 0, mismatched_fields: 0, mismatched_fields_list: '', verification_confidence: '' } });
    continue;
  }

  let matched = 0;
  let mismatched = 0;
  const mismatches = [];

  for (const field of fields) {
    const rawVerified = v[`verification_${field}`] ?? v[field];
    const a = normalize(o[field], field);
    const b = normalize(rawVerified, field);

    // Two empty values are not counted as a match.
    if (a === '' && b === '') continue;

    if (a === b) {
      matched++;
    } else {
      mismatched++;
      mismatches.push(field);
    }
  }

  let status = 'match';
  if (matched === 0 && mismatched === 0) status = 'not_verified';
  else if (mismatched > 0) status = 'mismatch';

  results.push({ json: { ...base, comparison_status: status,
    matched_fields: matched, mismatched_fields: mismatched,
    mismatched_fields_list: mismatches.join(', '),
    verification_confidence: v.verification_confidence ?? v.confidence ?? '' } });
}

return results;
